import json

with open('/app/resources/treasury_bulletin_1947_02.json', 'r') as f:
    data = json.load(f)

# Search for anything that mentions "High-grade corporate" more specifically
def search_recursive(obj, path='', target_keys=None):
    results = []
    if target_keys is None:
        target_keys = ['high-grade', 'corporate', 'bonds', 'yields']

    if isinstance(obj, dict):
        for k, v in obj.items():
            search_str = str(k).lower() + ' ' + str(v).lower()
            if any(t in search_str for t in target_keys):
                results.append(f"Found in {path}.{k}")
            results.extend(search_recursive(v, f'{path}.{k}', target_keys))
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            results.extend(search_recursive(item, f'{path}[{i}]', target_keys))
    return results

results = search_recursive(data)
for r in results[:30]:
    print(r)
